/**
 * SecurityConfig - Default security configurations
 * Used to configure security settings for different environments
 */
const SecurityConfig = {
  // Development environment
  development: {
    debug: true,
    csrf: {
      enabled: true,
      autoRefresh: true,
      refreshInterval: 30 * 60 * 1000,
      validateOnSubmit: true
    },
    jwt: {
      enabled: true,
      autoRefresh: true,
      refreshBeforeExpiry: 5 * 60 * 1000
    },
    validation: {
      enabled: true,
      sanitizeInput: true
    },
    csp: {
      enabled: false // Disabled in development for easier debugging
    }
  },

  // Production environment
  production: {
    debug: false,
    csrf: {
      enabled: true,
      autoRefresh: true,
      refreshInterval: 15 * 60 * 1000, // More frequent in production
      validateOnSubmit: true,
      tokenLength: 40
    },
    jwt: {
      enabled: true,
      autoRefresh: true,
      refreshBeforeExpiry: 2 * 60 * 1000, // Earlier refresh in production
      validateSignature: true
    },
    validation: {
      enabled: true,
      sanitizeInput: true,
      validateOutput: true
    },
    csp: {
      enabled: true,
      directives: {
        'default-src': ["'self'"],
        // Allow social SDK hosts required by the application (Google, Facebook, Telegram)
        // NOTE: Telegram's official widget uses dynamic code-generation which may require
        // 'unsafe-eval'. Enabling 'unsafe-eval' reduces the protection offered by CSP —
        // prefer a server-side or non-eval integration when possible.
        'script-src': ["'self'", "https://accounts.google.com", "https://apis.google.com", "https://connect.facebook.net", "https://telegram.org", "https://*.telegram.org", "'unsafe-inline'", "'unsafe-eval'"],
        'style-src': ["'self'", "'unsafe-inline'"],
        'img-src': ["'self'", "data:", "https:"],
        'connect-src': ["'self'"],
        'frame-src': ["'self'", "https://accounts.google.com", "https://www.google.com", "https://maps.google.com"],
        'object-src': ["'none'"]
      }
    }
  },

  /**
   * Get configuration for specific environment
   */
  getConfig(environment = 'production') {
    return this[environment] || this.production;
  },

  /**
   * Get merged configuration with overrides
   */
  getMergedConfig(environment = 'production', overrides = {}) {
    // Merge into a copy: the presets themselves must not change between calls
    const baseConfig = this.getConfig(environment);
    return this.mergeDeep(Object.assign({}, baseConfig), overrides);
  },

  /**
   * Deep merge utility; arrays are joined without duplicates (see
   * SecurityManager.mergeDeep)
   */
  mergeDeep(target, source) {
    const isObject = (obj) => obj && typeof obj === 'object' && !Array.isArray(obj);

    if (!isObject(target) || !isObject(source)) {
      return source;
    }

    Object.keys(source).forEach(key => {
      // Prototype-pollution guard: never copy __proto__/constructor/prototype
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') return;

      const targetValue = target[key];
      const sourceValue = source[key];

      if (Array.isArray(targetValue) && Array.isArray(sourceValue)) {
        target[key] = Array.from(new Set([...targetValue, ...sourceValue]));
      } else if (isObject(targetValue) && isObject(sourceValue)) {
        target[key] = this.mergeDeep(Object.assign({}, targetValue), sourceValue);
      } else {
        target[key] = sourceValue;
      }
    });

    return target;
  }
};

window.SecurityConfig = SecurityConfig;
